Object.freeze(GEOLOGY_PROFILES.profiles);
const SIZE = 65, LAST = 63, SCALE = 32;
const HEIGHTS = ["", "", "", ""].map(encoded => {
  const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
  const values = new Uint16Array(SIZE * SIZE);
  for (let i = 0; i < values.length; i++) values[i] = bytes[i * 2] | bytes[i * 2 + 1] << 8;
  return values;
});

/** Finite normalized relief in [0,1], exactly zero outside the padded domain. */
export function geologyProfileAt(profile, x, z) {
  if (!Number.isInteger(profile) || !HEIGHTS[profile] || !(x > -1 && x < 1 && z > -1 && z < 1)) return 0;
  const px = (x + 1) * SCALE, pz = (z + 1) * SCALE;
  const ix = Math.min(LAST, Math.floor(px)), iz = Math.min(LAST, Math.floor(pz));
  const tx = px - ix, tz = pz - iz, values = HEIGHTS[profile], i = iz * SIZE + ix;
  const a = values[i] + (values[i + 1] - values[i]) * tx;
  const b = values[i + SIZE] + (values[i + SIZE + 1] - values[i + SIZE]) * tx;
  return (a + (b - a) * tz) / 65535;
}
